n=22
g=[[0]*n for _ in range(n)]
def put(r,c,v):
    assert 0 <= r < n and 0 <= c < n, (r,c,v)
    assert g[r][c] in (0,v), (r,c,g[r][c],v)
    g[r][c]=v
# color 7, translated by (+2,-1)
for c in range(1,5): put(5,c,7); put(8,c,7)
put(6,1,7); put(7,1,7)
put(5,5,2); put(8,5,2)
# color 3, translated by (-9,-8)
for c in range(6,12): put(4,c,3)
for r in (5,6): put(r,6,3); put(r,11,3)
put(7,6,3); put(7,11,2)
put(8,6,3); put(8,5,2)
for c in range(6,9): put(9,c,3)
put(9,9,2)
# center 4
for r in range(8,11):
    for c in range(10,13): put(r,c,4)
for r,c in [(7,11),(9,9),(11,10),(11,12)]: put(r,c,2)
# color 9 translated by (-6,+7)
for r in (12,13): put(r,10,9); put(r,12,9)
for c in range(9,14): put(14,c,9)
put(11,10,2); put(11,12,2); put(15,9,2); put(15,13,2)
# color 8 translated by (+14,-7)
put(16,9,8); put(16,13,8)
for c in range(9,14): put(17,c,8)
put(15,9,2); put(15,13,2)
for row in g: print(' '.join(map(str,row)))
